use super::*;

/// [`root_blockers`] as a refusal message, or `None` when the root can move.
pub(crate) fn root_refusal(root_name: &str, root_src: &str) -> Option<String> {
    let blockers = root_blockers(root_src);
    if blockers.is_empty() {
        return None;
    }
    Some(format!(
        "src/{root_name} holds {} thing(s) an `include!`d file cannot: {}. An inner attribute is not \
         permitted in an included file at all — move a lint one to the manifest's [lints] table \
         (`#![forbid(unsafe_code)]` becomes `[lints.rust] unsafe_code = \"forbid\"`, stable since Rust \
         1.74) and re-run. One with no manifest home (`cfg_attr(…, windows_subsystem = …)`) means this \
         crate is not a candidate, and saying so is the honest answer",
        blockers.len(),
        blockers.join("; ")
    ))
}
